#nullable enable
// <auto-generated-ish>
// Hand-written proto wire codec helpers for the .NET Probe SDK.
//
// The gen/ tree mirrors what `buf generate --template sdk/dotnet/buf.gen.dotnet.yaml` (the
// buf.build/protocolbuffers/csharp:v33.4 plugin) would emit, but the codegen pipeline is not yet
// wired into CI (see gen/README.md). Until it is, these message classes are hand-written in the
// protoc-gen-csharp style: sealed classes with mutable properties, a oneof discriminator for
// AttributeValue, and binary (de)serialisation against Google.Protobuf's CodedOutputStream /
// CodedInputStream for wire compatibility with the Connect application/proto transport.
//
// Using the Google.Protobuf *stream* primitives (rather than implementing the full IMessage<T>
// descriptor apparatus) keeps the generated-style types lean while remaining binary-compatible
// with any real protobuf producer/consumer, including a future regenerated tree.
using System;
using System.Collections.Generic;
using Google.Protobuf;

namespace Emet.Sentinel.Proto;

/// <summary>A message that can write itself to and read itself from a protobuf stream.</summary>
internal interface ProtoMsg
{
    void Write(CodedOutputStream output);
    int CalcSize();
    void ReadFrom(CodedInputStream input);
}

/// <summary>
/// Wire-format helpers shared by every hand-written message. Each method pairs a writer with a
/// sizer of the same name suffixed <c>S</c>; the two MUST stay in lock-step or the on-the-wire
/// length-prefix will disagree with the bytes written.
/// </summary>
internal static class ProtoWire
{
    // --- writers -----------------------------------------------------------

    public static void WStr(CodedOutputStream o, int f, string v)
    {
        if (v.Length != 0) { o.WriteTag(f, WireFormat.WireType.LengthDelimited); o.WriteString(v); }
    }

    public static void WBool(CodedOutputStream o, int f, bool v)
    {
        if (v) { o.WriteTag(f, WireFormat.WireType.Varint); o.WriteBool(v); }
    }

    public static void WUInt64(CodedOutputStream o, int f, ulong v)
    {
        if (v != 0) { o.WriteTag(f, WireFormat.WireType.Varint); o.WriteUInt64(v); }
    }

    public static void WOptUInt64(CodedOutputStream o, int f, ulong? v)
    {
        if (v.HasValue) { o.WriteTag(f, WireFormat.WireType.Varint); o.WriteUInt64(v.GetValueOrDefault()); }
    }

    public static void WSInt64(CodedOutputStream o, int f, long v)
    {
        if (v != 0) { o.WriteTag(f, WireFormat.WireType.Varint); o.WriteSInt64(v); }
    }

    public static void WDouble(CodedOutputStream o, int f, double v)
    {
        if (v != 0) { o.WriteTag(f, WireFormat.WireType.Fixed64); o.WriteDouble(v); }
    }

    public static void WFixed64(CodedOutputStream o, int f, ulong v)
    {
        if (v != 0) { o.WriteTag(f, WireFormat.WireType.Fixed64); o.WriteFixed64(v); }
    }

    public static void WSFixed64(CodedOutputStream o, int f, long v)
    {
        if (v != 0) { o.WriteTag(f, WireFormat.WireType.Fixed64); o.WriteSFixed64(v); }
    }

    public static void WBytes(CodedOutputStream o, int f, ByteString v)
    {
        if (!v.IsEmpty) { o.WriteTag(f, WireFormat.WireType.LengthDelimited); o.WriteBytes(v); }
    }

    public static void WEnum<T>(CodedOutputStream o, int f, T v) where T : struct, Enum
    {
        int iv = (int)(object)v;
        if (iv != 0) { o.WriteTag(f, WireFormat.WireType.Varint); o.WriteInt32(iv); }
    }

    public static void WOptEnum<T>(CodedOutputStream o, int f, T? v) where T : struct, Enum
    {
        if (v.HasValue) { o.WriteTag(f, WireFormat.WireType.Varint); o.WriteInt32((int)(object)v.GetValueOrDefault()); }
    }

    public static void WMsg<T>(CodedOutputStream o, int f, T? m) where T : ProtoMsg
    {
        if (m != null)
        {
            int s = m.CalcSize();
            o.WriteTag(f, WireFormat.WireType.LengthDelimited);
            o.WriteLength(s);
            m.Write(o);
        }
    }

    public static void WRepStr(CodedOutputStream o, int f, List<string> xs)
    {
        for (int i = 0; i < xs.Count; i++) { o.WriteTag(f, WireFormat.WireType.LengthDelimited); o.WriteString(xs[i]); }
    }

    public static void WRepMsg<T>(CodedOutputStream o, int f, List<T> xs) where T : ProtoMsg
    {
        for (int i = 0; i < xs.Count; i++)
        {
            int s = xs[i].CalcSize();
            o.WriteTag(f, WireFormat.WireType.LengthDelimited);
            o.WriteLength(s);
            xs[i].Write(o);
        }
    }

    // Repeated scalar enums are packed by default in proto3, but an unpacked encoding is always
    // legal and any compliant reader accepts both. We encode unpacked (one tag per element) so
    // no packed-size precomputation is needed; the reader handles both.
    public static void WRepEnum<T>(CodedOutputStream o, int f, List<T> xs) where T : struct, Enum
    {
        for (int i = 0; i < xs.Count; i++) { o.WriteTag(f, WireFormat.WireType.Varint); o.WriteInt32((int)(object)xs[i]); }
    }

    // --- sizers -------------------------------------------------------------

    public static int Tag(int f) => CodedOutputStream.ComputeRawVarint32Size((uint)(f << 3));

    public static int StrS(int f, string v) => v.Length == 0 ? 0 : Tag(f) + CodedOutputStream.ComputeStringSize(v);

    public static int BoolS(int f, bool v) => v ? Tag(f) + 1 : 0;

    public static int UInt64S(int f, ulong v) => v == 0 ? 0 : Tag(f) + CodedOutputStream.ComputeUInt64Size(v);

    public static int OptUInt64S(int f, ulong? v) => v.HasValue ? Tag(f) + CodedOutputStream.ComputeUInt64Size(v.GetValueOrDefault()) : 0;

    public static int SInt64S(int f, long v) => v == 0 ? 0 : Tag(f) + CodedOutputStream.ComputeSInt64Size(v);

    public static int DoubleS(int f, double v) => v != 0 ? Tag(f) + 8 : 0;

    public static int Fixed64S(int f, ulong v) => v != 0 ? Tag(f) + 8 : 0;

    public static int SFixed64S(int f, long v) => v != 0 ? Tag(f) + 8 : 0;

    public static int BytesS(int f, ByteString v) => !v.IsEmpty ? Tag(f) + CodedOutputStream.ComputeBytesSize(v) : 0;

    public static int EnumS<T>(int f, T v) where T : struct, Enum
    {
        int iv = (int)(object)v;
        return iv == 0 ? 0 : Tag(f) + CodedOutputStream.ComputeInt32Size(iv);
    }

    public static int OptEnumS<T>(int f, T? v) where T : struct, Enum
    {
        return v.HasValue ? Tag(f) + CodedOutputStream.ComputeInt32Size((int)(object)v.GetValueOrDefault()) : 0;
    }

    public static int MsgS<T>(int f, T? m) where T : ProtoMsg
    {
        if (m == null) return 0;
        int s = m.CalcSize();
        return Tag(f) + CodedOutputStream.ComputeRawVarint32Size((uint)s) + s;
    }

    public static int RepStrS(int f, List<string> xs)
    {
        int total = 0;
        for (int i = 0; i < xs.Count; i++) total += Tag(f) + CodedOutputStream.ComputeStringSize(xs[i]);
        return total;
    }

    public static int RepMsgS<T>(int f, List<T> xs) where T : ProtoMsg
    {
        int total = 0;
        for (int i = 0; i < xs.Count; i++)
        {
            int s = xs[i].CalcSize();
            total += Tag(f) + CodedOutputStream.ComputeRawVarint32Size((uint)s) + s;
        }
        return total;
    }

    public static int RepEnumS<T>(int f, List<T> xs) where T : struct, Enum
    {
        int total = 0;
        for (int i = 0; i < xs.Count; i++) total += Tag(f) + CodedOutputStream.ComputeInt32Size((int)(object)xs[i]);
        return total;
    }

    // --- readers ------------------------------------------------------------

    /// <summary>
    /// Reads a length-delimited sub-message. A sub-message field's wire form is
    /// [tag][length][bytes]; after the tag, ReadBytes consumes the length and the bytes as a
    /// ByteString, which is then parsed on a fresh stream. This avoids PushLimit/PopLimit, which
    /// the pinned Google.Protobuf runtime does not expose publicly.
    /// </summary>
    public static T ReadMsg<T>(CodedInputStream input) where T : ProtoMsg, new()
    {
        ByteString bytes = input.ReadBytes();
        var sub = new T();
        if (!bytes.IsEmpty)
        {
            using var subInput = new CodedInputStream(bytes.ToByteArray());
            sub.ReadFrom(subInput);
        }
        return sub;
    }

    /// <summary>Reads a repeated enum field, accepting both packed and unpacked encodings.</summary>
    public static void ReadRepEnum<T>(CodedInputStream input, WireFormat.WireType wireType, List<T> xs) where T : struct, Enum
    {
        if (wireType == WireFormat.WireType.LengthDelimited)
        {
            int len = input.ReadLength();
            long limit = input.Position + len;
            while (input.Position < limit) xs.Add((T)(object)input.ReadInt32());
        }
        else
        {
            xs.Add((T)(object)input.ReadInt32());
        }
    }
}
